//! GUI translations (NOTES.md 6.9): the catalogs generated by `build.rs`, the language picked from
//! the Windows display language (override: env `HLAE_SETUP_LANG`, e.g. for translators).

use std::collections::HashMap;
use std::sync::OnceLock;

use windows_sys::Win32::Globalization::{GetUserPreferredUILanguages, MUI_LANGUAGE_NAME};

include!(concat!(env!("OUT_DIR"), "/l10n_index.rs"));

struct Selected {
    language: String,
    catalog: HashMap<String, String>,
}

static SELECTED: OnceLock<Selected> = OnceLock::new();

fn selected() -> &'static Selected {
    SELECTED.get_or_init(|| {
        let mut wanted: Vec<String> = std::env::var("HLAE_SETUP_LANG").into_iter().collect();
        wanted.extend(ui_languages());
        let language = pick(&wanted, CATALOGS.iter().map(|(lang, _)| *lang)).unwrap_or("en-US");
        let mut catalog = parse("en-US");
        if language != "en-US" {
            catalog.extend(parse(language)); // missing keys stay English
        }
        Selected {
            language: language.to_owned(),
            catalog,
        }
    })
}

fn parse(language: &str) -> HashMap<String, String> {
    CATALOGS
        .iter()
        .find(|(lang, _)| *lang == language)
        .and_then(|(_, json)| serde_json::from_str(json).ok())
        .unwrap_or_default()
}

/// First of `wanted` (e.g. `de-DE`, `pt-BR`) that we have, exact or by base language
/// (`de-DE` → `de`, `fr-CA` → `fr-FR`); case-insensitive.
fn pick<'a>(
    wanted: &[String],
    available: impl Iterator<Item = &'a str> + Clone,
) -> Option<&'a str> {
    for want in wanted {
        let want = want.to_ascii_lowercase();
        if let Some(lang) = available
            .clone()
            .find(|lang| lang.to_ascii_lowercase() == want)
        {
            return Some(lang);
        }
        let base = want.split('-').next().unwrap_or_default();
        let by_base = available.clone().find(|lang| {
            let lang = lang.to_ascii_lowercase();
            lang == base || lang.split('-').next() == Some(base)
        });
        if by_base.is_some() {
            return by_base;
        }
    }
    None
}

/// The user's preferred UI languages, e.g. `["de-DE", "en-US"]`.
fn ui_languages() -> Vec<String> {
    let (mut count, mut len) = (0u32, 0u32);
    // SAFETY: first call gets the buffer length, second fills a buffer of that size.
    unsafe {
        if GetUserPreferredUILanguages(
            MUI_LANGUAGE_NAME,
            &mut count,
            std::ptr::null_mut(),
            &mut len,
        ) == 0
        {
            return Vec::new();
        }
        let mut buffer = vec![0u16; len as usize];
        if GetUserPreferredUILanguages(MUI_LANGUAGE_NAME, &mut count, buffer.as_mut_ptr(), &mut len)
            == 0
        {
            return Vec::new();
        }
        String::from_utf16_lossy(&buffer)
            .split('\0')
            .filter(|s| !s.is_empty())
            .map(str::to_owned)
            .collect()
    }
}

/// Language of the GUI, e.g. `de` or `en-US`.
pub fn language() -> &'static str {
    &selected().language
}

/// All texts (English for missing translations).
pub fn catalog() -> &'static HashMap<String, String> {
    &selected().catalog
}

/// Text for `key` with `{name}` placeholders replaced; the key itself if unknown.
pub fn t(key: &str, args: &[(&str, &str)]) -> String {
    let mut text = catalog()
        .get(key)
        .cloned()
        .unwrap_or_else(|| key.to_owned());
    for (name, value) in args {
        text = text.replace(&format!("{{{name}}}"), value);
    }
    text
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn picks_exact_then_base_language() {
        let available = ["en-US", "de", "pt-BR", "pt-PT", "fr-FR", "zh-CN"];
        let pick = |wanted: &[&str]| {
            let wanted: Vec<String> = wanted.iter().map(|s| s.to_string()).collect();
            pick(&wanted, available.iter().copied())
        };
        assert_eq!(pick(&["de-DE"]), Some("de"));
        assert_eq!(pick(&["pt-PT"]), Some("pt-PT"));
        assert_eq!(pick(&["FR-CA"]), Some("fr-FR"));
        assert_eq!(pick(&["xx-YY", "pt-BR"]), Some("pt-BR"));
        assert_eq!(pick(&["xx-YY"]), None);
    }

    #[test]
    fn english_catalog_is_embedded() {
        assert!(CATALOGS.iter().any(|(lang, _)| *lang == "en-US"));
        assert!(!parse("en-US").is_empty());
        assert_eq!(t("NoSuchKey", &[]), "NoSuchKey");
    }
}
